SELECT d.id, 'en', 'Format & standard', '[["No published schema","No XML or UBL standard, no technical specification and no national platform. There is nothing to build against."],["Electronic is permitted","Invoices may be issued and kept electronically, and since 16 November 2023 without prior NBR approval."],["The condition on the system","An electronic system must stop entries being added, deleted or amended after the fact, and produce records on demand."]]', 'Bahrain''s e-invoicing programme is at procurement stage, not legislative. The January 2024 target that once circulated lapsed, and no enacted date exists.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Bahrain') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Formato y estándar', '[["Ningún esquema publicado","Ni norma XML o UBL, ni especificación técnica, ni plataforma nacional. No hay nada contra lo que construir."],["Lo electrónico está permitido","Las facturas pueden emitirse y conservarse electrónicamente, y desde el 16 de noviembre de 2023 sin autorización previa del NBR."],["La condición sobre el sistema","El sistema electrónico debe impedir que se añadan, borren o modifiquen asientos a posteriori, y producir los registros a requerimiento."]]', 'El programa de facturación electrónica de Baréin está en fase de licitación, no legislativa. El objetivo de enero de 2024 que circuló decayó y no existe ninguna fecha promulgada.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Bahrain') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Format und Standard', '[["Kein veröffentlichtes Schema","Kein XML- oder UBL-Standard, keine technische Spezifikation, keine nationale Plattform. Es gibt nichts, wogegen man bauen könnte."],["Elektronisch ist zulässig","Rechnungen dürfen elektronisch ausgestellt und aufbewahrt werden, seit dem 16. November 2023 ohne vorherige NBR-Genehmigung."],["Die Bedingung an das System","Ein elektronisches System muss nachträgliches Hinzufügen, Löschen oder Ändern von Einträgen verhindern und Aufzeichnungen auf Verlangen liefern."]]', 'Bahrains E-Invoicing-Programm steckt in der Beschaffungs-, nicht in der Gesetzgebungsphase. Das einst kursierende Ziel Januar 2024 ist verfallen; ein in Kraft gesetztes Datum gibt es nicht.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Bahrain') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Format et norme', '[["Aucun schéma publié","Ni norme XML ou UBL, ni spécification technique, ni plateforme nationale. Il n''y a rien contre quoi développer."],["L''électronique est permis","Les factures peuvent être émises et conservées sous forme électronique, et depuis le 16 novembre 2023 sans accord préalable du NBR."],["La condition sur le système","Un système électronique doit empêcher l''ajout, la suppression ou la modification d''écritures après coup, et produire les registres sur demande."]]', 'Le programme de facturation électronique de Bahreïn en est au stade des marchés publics, pas de la loi. L''échéance de janvier 2024 qui a circulé est caduque et aucune date n''est promulguée.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Bahrain') AND d.section = 'file_format' AND d.sort_order = 0;
