INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Identifiers & registration', '[["VAT account number","The NBR issues a 15-digit numeric VAT account number on registration, and it must appear on a tax invoice."],["Thresholds","Registration is compulsory above BHD 37,500 of annual taxable supplies and optional from BHD 18,750."],["Non-residents","A non-resident making taxable supplies in Bahrain registers from its first supply, with no threshold to clear."],["A representative is optional","A non-resident may register directly or through a representative the NBR has approved. One is not compulsory."]]', 'The 15-digit format is not stated in any NBR document we could reach — nbr.gov.bh refused every automated request — so it rests on two secondary sources and one registrant''s own published number.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Bahrain') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Identificadores y registro', '[["Número de cuenta de IVA","El NBR emite al registrarse un número de cuenta de IVA de 15 dígitos numéricos, que debe figurar en la factura fiscal."],["Umbrales","El registro es obligatorio por encima de 37.500 BHD de entregas gravadas anuales y voluntario desde 18.750 BHD."],["No residentes","Un no residente que realice entregas gravadas en Baréin se registra desde su primera entrega, sin umbral que superar."],["El representante es opcional","Un no residente puede registrarse directamente o mediante un representante aprobado por el NBR. No es obligatorio tenerlo."]]', 'El formato de 15 dígitos no consta en ningún documento del NBR al que pudiéramos acceder — nbr.gov.bh rechazó toda petición automatizada — por lo que se apoya en dos fuentes secundarias y en el número publicado por un registrado.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Bahrain') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Kennungen und Registrierung', '[["USt-Kontonummer","Das NBR vergibt bei der Registrierung eine 15-stellige numerische USt-Kontonummer, die auf der Steuerrechnung stehen muss."],["Schwellenwerte","Die Registrierung ist ab 37.500 BHD steuerbarer Jahresumsätze verpflichtend und ab 18.750 BHD freiwillig möglich."],["Gebietsfremde","Ein Gebietsfremder mit steuerbaren Umsätzen in Bahrain registriert sich ab dem ersten Umsatz, ohne Schwellenwert."],["Vertreter ist optional","Ein Gebietsfremder kann sich direkt oder über einen vom NBR zugelassenen Vertreter registrieren. Pflicht ist das nicht."]]', 'Das 15-stellige Format steht in keinem erreichbaren NBR-Dokument — nbr.gov.bh wies jede automatisierte Anfrage ab — es stützt sich daher auf zwei Sekundärquellen und die veröffentlichte Nummer eines Registrierten.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Bahrain') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Identifiants et enregistrement', '[["Numéro de compte TVA","Le NBR attribue à l''immatriculation un numéro de compte TVA à 15 chiffres, qui doit figurer sur la facture fiscale."],["Seuils","L''immatriculation est obligatoire au-delà de 37 500 BHD de livraisons taxables annuelles et facultative dès 18 750 BHD."],["Non-résidents","Un non-résident réalisant des livraisons taxables à Bahreïn s''immatricule dès sa première livraison, sans seuil à franchir."],["Le représentant est facultatif","Un non-résident peut s''immatriculer directement ou via un représentant agréé par le NBR. Ce n''est pas une obligation."]]', 'Le format à 15 chiffres ne figure dans aucun document du NBR que nous ayons pu atteindre — nbr.gov.bh a refusé toute requête automatisée — il repose donc sur deux sources secondaires et le numéro publié par un assujetti.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Bahrain') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Bahrain';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Mandatory content', '[["A tax invoice does exist","Bahrain has VAT at 10%, so tax-invoice content rules bind whether or not the invoice is electronic."],["What it must show","The words Tax Invoice, both parties, the dates, a sequential number, the supply and the tax — with values in Bahraini dinars."],["Arabic is not required","Unlike Saudi Arabia, Bahrain requires no Arabic on an invoice. Records and books may be kept in Arabic or English."],["Simplified at BHD 500","Available where the customer is unregistered or the consideration is BHD 500 or less; the customer''s details may be omitted."]]', 'The Executive Regulations themselves could not be read — nbr.gov.bh returned 403 on every path — so the figures rest on three firms independently quoting Articles 52 and 53. An NBR guide update of 29 July 2026 may have moved this.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Bahrain') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Contenido obligatorio', '[["La factura fiscal sí existe","Baréin tiene IVA al 10%, de modo que las reglas de contenido de la factura fiscal obligan sea o no electrónica."],["Qué debe mostrar","Las palabras Tax Invoice, ambas partes, las fechas, un número correlativo, la operación y el impuesto, con importes en dinares bareiníes."],["El árabe no es obligatorio","A diferencia de Arabia Saudí, Baréin no exige árabe en la factura. Los libros y registros pueden llevarse en árabe o en inglés."],["Simplificada en 500 BHD","Disponible si el cliente no está registrado o la contraprestación no supera 500 BHD; pueden omitirse los datos del cliente."]]', 'El Reglamento Ejecutivo no pudo leerse — nbr.gov.bh devolvió 403 en todas las rutas — por lo que las cifras se apoyan en tres firmas que citan por separado los artículos 52 y 53. Una actualización de la guía del NBR del 29 de julio de 2026 podría haberlo cambiado.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Bahrain') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Pflichtangaben', '[["Eine Steuerrechnung gibt es","Bahrain erhebt 10% Umsatzsteuer, daher gelten Inhaltsregeln für die Steuerrechnung, ob elektronisch oder nicht."],["Was darauf stehen muss","Die Worte Tax Invoice, beide Parteien, die Daten, eine fortlaufende Nummer, der Umsatz und die Steuer — Beträge in Bahrain-Dinar."],["Arabisch ist nicht Pflicht","Anders als Saudi-Arabien verlangt Bahrain kein Arabisch auf der Rechnung. Bücher und Aufzeichnungen dürfen arabisch oder englisch sein."],["Vereinfacht ab 500 BHD","Möglich, wenn der Kunde nicht registriert ist oder das Entgelt 500 BHD nicht übersteigt; Kundendaten dürfen entfallen."]]', 'Die Durchführungsverordnung selbst war nicht lesbar — nbr.gov.bh lieferte auf jedem Pfad 403 — die Zahlen stützen sich daher auf drei Kanzleien, die unabhängig die Artikel 52 und 53 zitieren. Ein NBR-Leitfaden-Update vom 29. Juli 2026 könnte dies verschoben haben.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Bahrain') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Mentions obligatoires', '[["La facture fiscale existe bien","Bahreïn applique une TVA de 10%, si bien que les règles de contenu de la facture fiscale s''imposent, électronique ou non."],["Ce qu''elle doit porter","Les mots Tax Invoice, les deux parties, les dates, un numéro séquentiel, l''opération et la taxe — montants en dinars bahreïnis."],["L''arabe n''est pas exigé","Contrairement à l''Arabie saoudite, Bahreïn n''exige pas d''arabe sur la facture. Livres et registres peuvent être en arabe ou en anglais."],["Simplifiée à 500 BHD","Possible si le client n''est pas immatriculé ou si la contrepartie n''excède pas 500 BHD ; les données du client peuvent être omises."]]', 'Le règlement d''exécution lui-même n''a pas pu être lu — nbr.gov.bh a renvoyé 403 sur chaque chemin — les chiffres reposent donc sur trois cabinets citant séparément les articles 52 et 53. Une mise à jour du guide du NBR du 29 juillet 2026 a pu modifier cela.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Bahrain') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Bahrain';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Archiving', '[["Ten years","VAT records and accounting books are kept ten years. The NBR doubled the original five in February 2024."],["Real estate runs longer","Records relating to real estate are kept fifteen years from the end of the tax period they relate to."],["Capital assets","Records must outlast the adjustment period — five years for movable capital assets and ten for immovable ones."],["Electronic is fine","Records and invoices may be held electronically where they cannot be altered and can be produced on demand."]]', 'No decision number for the 2024 extension surfaced, and no source addresses whether it also moved the fifteen-year real-estate period. Whether records must be held inside Bahrain is unresolved.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Bahrain') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Conservación', '[["Diez años","Los registros de IVA y los libros contables se conservan diez años. El NBR duplicó los cinco originales en febrero de 2024."],["Los inmuebles, más","Los registros relativos a bienes inmuebles se conservan quince años desde el fin del periodo fiscal al que se refieren."],["Bienes de capital","Los registros deben sobrevivir al periodo de ajuste: cinco años para los bienes muebles y diez para los inmuebles."],["Lo electrónico vale","Los registros y las facturas pueden conservarse electrónicamente si no pueden alterarse y pueden producirse a requerimiento."]]', 'No apareció número de resolución para la ampliación de 2024, y ninguna fuente aborda si también movió el plazo de quince años de los inmuebles. Si los registros deben guardarse en Baréin sigue sin resolverse.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Bahrain') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Aufbewahrung', '[["Zehn Jahre","USt-Aufzeichnungen und Bücher werden zehn Jahre aufbewahrt. Das NBR verdoppelte die ursprünglichen fünf im Februar 2024."],["Immobilien länger","Aufzeichnungen zu Immobilien werden fünfzehn Jahre ab dem Ende des betroffenen Steuerzeitraums aufbewahrt."],["Anlagegüter","Die Aufzeichnungen müssen den Berichtigungszeitraum überdauern — fünf Jahre bei beweglichen, zehn bei unbeweglichen Anlagegütern."],["Elektronisch ist zulässig","Aufzeichnungen und Rechnungen dürfen elektronisch gehalten werden, sofern sie unveränderbar sind und auf Verlangen vorgelegt werden können."]]', 'Für die Verlängerung von 2024 tauchte keine Beschlussnummer auf, und keine Quelle behandelt, ob sie auch die fünfzehnjährige Immobilienfrist verschob. Ob Unterlagen in Bahrain liegen müssen, ist ungeklärt.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Bahrain') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Conservation', '[["Dix ans","Les registres de TVA et les livres comptables sont conservés dix ans. Le NBR a doublé les cinq ans d''origine en février 2024."],["L''immobilier plus longtemps","Les registres relatifs aux biens immobiliers sont conservés quinze ans à compter de la fin de la période fiscale concernée."],["Biens d''équipement","Les registres doivent survivre à la période de régularisation — cinq ans pour les biens mobiliers, dix pour les immeubles."],["L''électronique convient","Registres et factures peuvent être conservés sous forme électronique s''ils sont inaltérables et peuvent être produits sur demande."]]', 'Aucun numéro de décision n''est apparu pour la prolongation de 2024, et aucune source n''indique si elle a aussi déplacé le délai de quinze ans pour l''immobilier. La question d''une conservation à Bahreïn reste ouverte.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Bahrain') AND d.section = 'file_format' AND d.sort_order = 3;

