SELECT d.id, 'en', 'Format & standard', '[["No published schema","The General Tax Authority has published no XML or UBL standard, no technical specification and no platform."],["The draft law","A draft law and its executive regulations were approved by the Council of Ministers on 6 May 2026. Neither text has been published."],["Not yet enacted","The Shura Council had not taken it up before rising on 6 July 2026. It is not passed, not assented to and not gazetted."]]', 'Two vendor pages publish detailed Qatari specifications — UBL 2.1, SHA-256 hashing, ECDSA keys, a GTA data dictionary. No Qatari authority has published any of it; it reads as Saudi Arabia''s specification transposed.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Qatar') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Formato y estándar', '[["Ningún esquema publicado","La Autoridad General Tributaria no ha publicado norma XML o UBL alguna, ni especificación técnica, ni plataforma."],["El proyecto de ley","El Consejo de Ministros aprobó un proyecto de ley y su reglamento ejecutivo el 6 de mayo de 2026. Ninguno de los textos se ha publicado."],["Aún no promulgada","El Consejo de la Shura no lo abordó antes de levantar sesión el 6 de julio de 2026. No está aprobada, ni sancionada, ni publicada en el boletín."]]', 'Dos páginas de proveedores publican especificaciones cataríes detalladas: UBL 2.1, hash SHA-256, claves ECDSA, un diccionario de datos de la GTA. Ninguna autoridad catarí ha publicado nada de eso; parece la especificación saudí trasladada.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Qatar') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Format und Standard', '[["Kein veröffentlichtes Schema","Die General Tax Authority hat weder einen XML- oder UBL-Standard noch eine technische Spezifikation oder Plattform veröffentlicht."],["Der Gesetzentwurf","Der Ministerrat billigte am 6. Mai 2026 einen Gesetzentwurf samt Durchführungsverordnung. Keiner der Texte wurde veröffentlicht."],["Noch nicht in Kraft","Der Schura-Rat hatte ihn vor der Vertagung am 6. Juli 2026 nicht aufgerufen. Nicht beschlossen, nicht sanktioniert, nicht verkündet."]]', 'Zwei Anbieterseiten veröffentlichen detaillierte katarische Spezifikationen — UBL 2.1, SHA-256-Hashing, ECDSA-Schlüssel, ein GTA-Datenwörterbuch. Keine katarische Behörde hat davon etwas veröffentlicht; es liest sich wie die saudische Spezifikation, übertragen.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Qatar') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
