INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Identifiers & registration', '[["Tax Identification Number","Ten digits opening with 5, issued by the General Tax Authority. Qatar Financial Centre firms get a T-prefixed number instead."],["Who registers","Anyone carrying on an activity or earning taxable income, within sixty days of approval to start."],["Everything runs on Dhareeba","Registration, tax cards, returns and withholding all go through the GTA''s Dhareeba portal. The old TAS system closed in 2020."],["Exemption is not excusal","An exempt Qatari or GCC-owned company still registers and still files a return, on a simplified form if it is small."]]', 'The ten-digit format is not published by the General Tax Authority; it rests on the OECD''s jurisdiction sheet, which is compiled from information the jurisdiction supplies.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Qatar') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Identificadores y registro', '[["Número de identificación fiscal","Diez dígitos que empiezan por 5, emitidos por la Autoridad General Tributaria. Las firmas del Qatar Financial Centre reciben en cambio un número con prefijo T."],["Quién se registra","Quien ejerza una actividad u obtenga renta gravable, dentro de los sesenta días siguientes a la aprobación para iniciarla."],["Todo pasa por Dhareeba","Registro, tarjetas fiscales, declaraciones y retenciones van por el portal Dhareeba de la GTA. El antiguo sistema TAS cerró en 2020."],["La exención no exime","Una empresa exenta catarí o del CCG se registra igualmente y presenta declaración, en formulario simplificado si es pequeña."]]', 'La Autoridad General Tributaria no publica el formato de diez dígitos; procede de la ficha jurisdiccional de la OCDE, elaborada con datos que aporta la propia jurisdicción.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Qatar') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Kennungen und Registrierung', '[["Steuernummer","Zehn Ziffern, beginnend mit 5, vergeben von der General Tax Authority. Firmen im Qatar Financial Centre erhalten stattdessen eine Nummer mit T-Präfix."],["Wer sich registriert","Wer eine Tätigkeit ausübt oder steuerpflichtige Einkünfte erzielt, binnen sechzig Tagen nach der Genehmigung zum Start."],["Alles läuft über Dhareeba","Registrierung, Steuerkarten, Erklärungen und Quellensteuer laufen über das GTA-Portal Dhareeba. Das alte TAS-System schloss 2020."],["Befreiung entbindet nicht","Ein befreites katarisches oder GCC-eigenes Unternehmen registriert sich dennoch und gibt eine Erklärung ab, vereinfacht wenn es klein ist."]]', 'Das zehnstellige Format wird von der General Tax Authority nicht veröffentlicht; es stammt aus dem OECD-Länderblatt, das aus Angaben der Jurisdiktion zusammengestellt wird.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Qatar') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Identifiants et enregistrement', '[["Numéro d''identification fiscale","Dix chiffres commençant par 5, délivrés par l''Autorité générale des impôts. Les sociétés du Qatar Financial Centre reçoivent un numéro préfixé T."],["Qui s''immatricule","Toute personne exerçant une activité ou percevant un revenu imposable, dans les soixante jours suivant l''autorisation de démarrer."],["Tout passe par Dhareeba","Immatriculation, cartes fiscales, déclarations et retenues passent par le portail Dhareeba de la GTA. L''ancien système TAS a fermé en 2020."],["L''exonération n''exempte pas","Une société exonérée qatarie ou du CCG s''immatricule quand même et dépose une déclaration, sur formulaire simplifié si elle est petite."]]', 'Le format à dix chiffres n''est pas publié par l''Autorité générale des impôts ; il provient de la fiche de l''OCDE, établie à partir des informations fournies par la juridiction.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Qatar') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Qatar';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Mandatory content', '[["There is no tax invoice","Qatar has no VAT, so no tax-invoice rules exist. Nothing in the income tax law prescribes what an invoice must show."],["The duty is bookkeeping","What the law requires is books: a general journal, a general ledger and an inventory ledger, with supporting documents."],["Invoices are evidence","An invoice matters as proof. A cost is deductible only if actually incurred and backed by documents such as contracts and invoices."],["Arabic for the filing","Financial statements filed with the GTA must be in Arabic, as must correspondence. No riyal-only rule was found for invoices."]]', 'This is the distinction that matters: Qatar imposes a bookkeeping and evidentiary duty, not an invoice-content duty. A search of the consolidated law and regulations found no operative provision prescribing what an invoice must contain.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Qatar') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Contenido obligatorio', '[["No existe la factura fiscal","Catar no tiene IVA, así que no hay reglas de factura fiscal. Nada en la ley del impuesto sobre la renta prescribe qué debe mostrar una factura."],["El deber es llevar libros","Lo que la ley exige son libros: diario general, mayor general y libro de inventarios, con sus documentos justificativos."],["Las facturas son prueba","La factura cuenta como prueba. Un gasto solo es deducible si se incurrió realmente y está respaldado por contratos y facturas."],["Árabe para la presentación","Los estados financieros presentados a la GTA deben ir en árabe, igual que la correspondencia. No se halló regla de solo riales para facturas."]]', 'Esta es la distinción que importa: Catar impone un deber de contabilidad y de prueba, no un deber de contenido de la factura. Una búsqueda en la ley y el reglamento consolidados no halló disposición alguna que prescriba el contenido de una factura.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Qatar') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Pflichtangaben', '[["Eine Steuerrechnung gibt es nicht","Katar hat keine Mehrwertsteuer, also keine Regeln zur Steuerrechnung. Das Einkommensteuerrecht schreibt keinen Rechnungsinhalt vor."],["Die Pflicht ist Buchführung","Verlangt sind Bücher: Grundbuch, Hauptbuch und Inventarbuch, mit den zugehörigen Belegen."],["Rechnungen sind Nachweis","Die Rechnung zählt als Beleg. Eine Ausgabe ist nur abziehbar, wenn sie tatsächlich anfiel und durch Verträge und Rechnungen belegt ist."],["Arabisch für die Einreichung","Bei der GTA eingereichte Abschlüsse müssen arabisch sein, ebenso der Schriftwechsel. Eine Riyal-Pflicht für Rechnungen war nicht auffindbar."]]', 'Das ist der entscheidende Unterschied: Katar erlegt eine Buchführungs- und Nachweispflicht auf, keine Pflicht zum Rechnungsinhalt. Eine Suche im konsolidierten Gesetz und der Verordnung fand keine Vorschrift zum Rechnungsinhalt.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Qatar') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Mentions obligatoires', '[["Il n''y a pas de facture fiscale","Le Qatar n''a pas de TVA, donc aucune règle de facture fiscale. Rien dans la loi sur l''impôt sur le revenu ne prescrit le contenu d''une facture."],["L''obligation est comptable","Ce que la loi exige, ce sont des livres : journal général, grand livre et livre d''inventaire, avec leurs pièces justificatives."],["Les factures font preuve","La facture vaut preuve. Une charge n''est déductible que si elle a réellement été engagée et est appuyée par contrats et factures."],["L''arabe pour le dépôt","Les états financiers déposés auprès de la GTA doivent être en arabe, de même que la correspondance. Aucune règle de riyal seul n''a été trouvée."]]', 'C''est la distinction qui compte : le Qatar impose une obligation comptable et probatoire, non une obligation de contenu de facture. Une recherche dans la loi et le règlement consolidés n''a trouvé aucune disposition prescrivant le contenu d''une facture.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Qatar') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Qatar';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Archiving', '[["Ten years","Books, records and supporting documents are kept ten years after the year they relate to."],["At the place of business","Records stay where the activity is carried on, so in practice inside Qatar. The GTA may release them early in set cases."],["Electronic is permitted","Books may be kept on computer systems where the conditions on security, data integrity and GTA access are met."],["Traders keep them too","Separately, the Trading Regulation Law gives ten years for the journal, ledger and inventory book, and five for business correspondence."]]', 'The retention rule sits at Executive Regulations Articles 35 to 36 and is cited as a range: two passes over the same authoritative text split the sub-clause differently while agreeing on the substance. Al Meezan refused every request.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Qatar') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Conservación', '[["Diez años","Los libros, registros y documentos justificativos se conservan diez años después del ejercicio al que se refieren."],["En el lugar de actividad","Los registros permanecen donde se ejerce la actividad, es decir en la práctica dentro de Catar. La GTA puede liberarlos antes en casos tasados."],["Lo electrónico está permitido","Los libros pueden llevarse en sistemas informáticos si se cumplen las condiciones de seguridad, integridad de datos y acceso de la GTA."],["Los comerciantes también","Aparte, la Ley de Regulación del Comercio fija diez años para diario, mayor e inventario, y cinco para la correspondencia mercantil."]]', 'La regla de conservación está en los artículos 35 a 36 del Reglamento Ejecutivo y se cita como rango: dos lecturas del mismo texto autorizado dividieron el apartado de forma distinta coincidiendo en el fondo. Al Meezan rechazó toda petición.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Qatar') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Aufbewahrung', '[["Zehn Jahre","Bücher, Aufzeichnungen und Belege werden zehn Jahre nach dem Jahr aufbewahrt, auf das sie sich beziehen."],["Am Ort der Tätigkeit","Die Unterlagen bleiben dort, wo die Tätigkeit ausgeübt wird, also praktisch in Katar. Die GTA kann sie in festgelegten Fällen früher freigeben."],["Elektronisch ist zulässig","Bücher dürfen auf EDV-Systemen geführt werden, sofern die Bedingungen zu Sicherheit, Datenintegrität und GTA-Zugriff erfüllt sind."],["Kaufleute ebenso","Daneben gibt das Handelsregelungsgesetz zehn Jahre für Grundbuch, Hauptbuch und Inventarbuch und fünf für den Geschäftsschriftwechsel."]]', 'Die Aufbewahrungsregel steht in den Artikeln 35 bis 36 der Durchführungsverordnung und wird als Spanne zitiert: zwei Durchgänge durch denselben maßgeblichen Text teilten den Absatz unterschiedlich, stimmten aber inhaltlich überein. Al Meezan wies jede Anfrage ab.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Qatar') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Conservation', '[["Dix ans","Les livres, registres et pièces justificatives sont conservés dix ans après l''exercice auquel ils se rapportent."],["Au lieu d''activité","Les registres restent là où l''activité est exercée, donc en pratique au Qatar. La GTA peut les libérer plus tôt dans des cas définis."],["L''électronique est permis","Les livres peuvent être tenus sur systèmes informatiques si les conditions de sécurité, d''intégrité des données et d''accès de la GTA sont remplies."],["Les commerçants aussi","Par ailleurs, la loi sur la réglementation du commerce fixe dix ans pour le journal, le grand livre et l''inventaire, et cinq pour la correspondance."]]', 'La règle de conservation figure aux articles 35 à 36 du règlement d''exécution et est citée comme une fourchette : deux lectures du même texte faisant foi ont découpé l''alinéa différemment tout en s''accordant sur le fond. Al Meezan a refusé chaque requête.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Qatar') AND d.section = 'file_format' AND d.sort_order = 3;

